package com.luckymod.client;

import com.luckymod.entity.EntityLucky;

import net.minecraft.client.model.ModelBase;
import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.util.MathHelper;

/**
 * Lucky with two looks, both adapted from the Better Dogs pack (MrBlueYeti):
 * furry = Cairn terrier, shaved (after the shears) = Chihuahua body with the Cairn's face.
 * The geometry lives in LuckyRigs (generated by tools/gen_betterdogs.py).
 */
public class ModelLucky extends ModelBase {

    private static final float PI = (float) Math.PI;
    private static final float DEG = PI / 180.0F;
    /** How far the body sinks when Lucky lies down. */
    private static final float LIE_DROP = 3.0F;

    private final LuckyRig furry;
    private final LuckyRig shaved;
    private LuckyRig rig;

    private boolean sitting;
    private boolean tamed;
    private float pet; // 0..1 while being petted

    public ModelLucky() {
        textureWidth = 128;
        textureHeight = 64;
        furry = LuckyRigs.furry(this);
        shaved = LuckyRigs.shaved(this);
        rig = furry;
    }

    @Override
    public void render(Entity entity, float limbSwing, float limbSwingAmount, float age, float headYaw,
            float headPitch, float scale) {
        setRotationAngles(limbSwing, limbSwingAmount, age, headYaw, headPitch, scale, entity);
        rig.render(scale);
    }

    /** Pose that depends on the entity state: which coat, lying down, head tilt, shaking off water. */
    @Override
    public void setLivingAnimations(EntityLivingBase entity, float limbSwing, float limbSwingAmount,
            float partialTicks) {
        EntityLucky lucky = entity instanceof EntityLucky ? (EntityLucky) entity : null;
        rig = lucky != null && lucky.isSheared() ? shaved : furry;
        rig.reset();
        if (lucky == null) return;
        sitting = lucky.isSitting();
        tamed = lucky.isTamed();
        pet = lucky.getPetAmount(partialTicks);

        if (sitting) {
            // lies down like a little sphinx: front paws forward, back paws behind
            rig.body.rotationPointY += LIE_DROP;
            rig.head.rotationPointY += LIE_DROP;
            rig.tail.rotationPointY += LIE_DROP;
            rig.legFrontLeft.rotationPointY += LIE_DROP;
            rig.legFrontRight.rotationPointY += LIE_DROP;
            rig.legBackLeft.rotationPointY += LIE_DROP;
            rig.legBackRight.rotationPointY += LIE_DROP;
            rig.legFrontLeft.rotateAngleX = -PI / 2.0F;
            rig.legFrontRight.rotateAngleX = -PI / 2.0F;
            rig.legBackLeft.rotateAngleX = PI / 2.0F;
            rig.legBackRight.rotateAngleX = PI / 2.0F;
            rig.legBackLeft.rotateAngleY = 0.25F;
            rig.legBackRight.rotateAngleY = -0.25F;
        }

        float petTilt = MathHelper.sin(pet * PI) * 0.35F;
        rig.head.rotateAngleZ = lucky.getInterestedAngle(partialTicks) + lucky.getShakeAngle(partialTicks, 0.0F)
                + petTilt;
        rig.body.rotateAngleZ = lucky.getShakeAngle(partialTicks, -0.16F);
        rig.tail.rotateAngleZ = lucky.getShakeAngle(partialTicks, -0.2F);
    }

    @Override
    public void setRotationAngles(float limbSwing, float limbSwingAmount, float age, float headYaw,
            float headPitch, float scale, Entity entity) {
        rig.head.rotateAngleX = headPitch * DEG;
        rig.head.rotateAngleY = headYaw * DEG;

        float stride = MathHelper.cos(limbSwing * 0.6662F);
        float tailWag;
        if (sitting) {
            tailWag = MathHelper.sin(age * 0.35F) * 0.25F;
        } else {
            float swing = stride * 1.4F * limbSwingAmount;
            rig.legFrontLeft.rotateAngleX = swing;
            rig.legBackRight.rotateAngleX = swing;
            rig.legFrontRight.rotateAngleX = -swing;
            rig.legBackLeft.rotateAngleX = -swing;
            rig.head.rotationPointY += Math.abs(stride) * 0.3F * limbSwingAmount; // little bounce
            tailWag = stride * 0.8F * limbSwingAmount;
            if (tamed) tailWag += MathHelper.sin(age * 0.9F) * 0.3F; // happy dog
        }
        if (pet > 0.0F) {
            tailWag += MathHelper.sin(age * 2.2F) * 0.6F * pet; // being petted: wags like crazy
            rig.head.rotateAngleX += 0.25F * pet; // leans into the hand
        }
        rig.tail.rotateAngleY = tailWag * rig.tailWagY;
        rig.tail.rotateAngleZ += tailWag * rig.tailWagZ;

        // every few seconds an ear flicks
        float t = age % 90.0F;
        if (t < 5.0F) rig.earLeft.rotateAngleZ -= MathHelper.sin(t / 5.0F * PI) * 0.4F;
        float t2 = (age + 47.0F) % 110.0F;
        if (t2 < 5.0F) rig.earRight.rotateAngleZ += MathHelper.sin(t2 / 5.0F * PI) * 0.4F;
        if (pet > 0.0F) { // ears relax back while petted
            rig.earLeft.rotateAngleX -= 0.5F * pet;
            rig.earRight.rotateAngleX -= 0.5F * pet;
        }
    }
}
